export interface components {
    schemas: {
        /**
         * @description RFC 9457 Problem Details，v3 端点的错误响应体。
         *     由 bootstrap/app.php 的异常处理器统一渲染，控制器不自己拼。
         *     media type 是 application/problem+json。
         */
        ProblemDetails: {
            /**
             * @description 问题类型标识，形如 urn:problem:not-found
             * @example urn:problem:not-found
             */
            type: string;
            /** @description 稳定的英文摘要，同类问题恒定，供机器识别 */
            title: string;
            status: number;
            /** @description 面向人的文案，已本地化；5xx 在生产环境会省略以免泄露内部信息 */
            detail?: string;
            /** @description 出问题的请求 URI */
            instance?: string;
            /** @description 字段级校验错误，仅 422 时出现 */
            errors?: {
                [key: string]: string[];
            };
        };
        /**
         * @description v3 列表接口的分页信息，由 Laravel paginator 生成。
         *     刻意不含 links / path：那些是 APP_URL 拼出的绝对地址，反代下会拼错，前端也用不到。
         *     手工分页的接口会附加自己的字段（如 has_more / first_para / page_size）。
         */
        PaginationMeta: {
            current_page: number;
            per_page?: number;
            total: number;
            last_page?: number;
            from?: number | null;
            to?: number | null;
        };
        Envelope: {
            ok?: boolean;
            message?: string;
            /** @description 业务数据，形状随接口而定 */
            data?: unknown;
        };
    };
    responses: {
        /** @description 未登录或无权限 */
        Unauthorized: {
            headers: {
                [name: string]: unknown;
            };
            content: {
                "application/json": components["schemas"]["Envelope"];
            };
        };
        /** @description 未登录或无权限（v3） */
        ProblemUnauthorized: {
            headers: {
                [name: string]: unknown;
            };
            content: {
                "application/problem+json": components["schemas"]["ProblemDetails"];
            };
        };
        /** @description 参数校验失败（v3） */
        ProblemValidation: {
            headers: {
                [name: string]: unknown;
            };
            content: {
                "application/problem+json": components["schemas"]["ProblemDetails"];
            };
        };
        /** @description 参数校验失败 */
        ValidationError: {
            headers: {
                [name: string]: unknown;
            };
            content: {
                "application/json": {
                    message?: string;
                    errors?: {
                        [key: string]: string[];
                    };
                };
            };
        };
    };
    parameters: never;
    requestBodies: never;
    headers: never;
    pathItems: never;
}
